output_text:
[
  {
    "id": "pedestrian_only_single_file_aisle",
    "text": "Shopping carts are prohibited in single-file aisles between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "twoSidedShelfAisle": {
          "and": [
            "singleFileAisle",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "twoSidedShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_single_file",
    "text": "A shopper must not move a cart into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFile": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFile"
    }
  },
  {
    "id": "no_cart_shelf_service_in_single_file",
    "text": "Shelf interactions in a single-file aisle must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfServiceSpot": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "singleFileShelfServiceSpot"
        ]
      }
    }
  },
  {
    "id": "cart_for_cart_accessible_shelf_service",
    "text": "At shelf-service locations that are wide enough for carts, shoppers must not interact with the shelf without their cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartAccessibleShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            },
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "hasCart"
          },
          "cartAccessibleShelfFace"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_wide_clear_bay",
    "text": "A cart may only be set down in a wide clear bay, not beside shelves or inside a constricted aisle.",
    "abstraction": {
      "state_properties": {
        "wideClearBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "wideClearBay"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_roaming_outside_pedestrian_detour",
    "text": "After taking a cart, a shopper may move without it only in a pedestrian-only aisle or at a wide mouth used as the cart-parking point.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartParkMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "eq": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "pedestrianDetourArea": {
          "or": [
            "singleFileAisle",
            "cartParkMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "pedestrianDetourArea"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_cart_after_pedestrian_aisle",
    "text": "A shopper who enters a pedestrian-only aisle without a cart is obliged to reclaim the cart afterward.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        },
        "cartRecovered": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileWithoutCart",
      "discharge": "cartRecovered"
    }
  },
  {
    "id": "return_to_wide_bay_after_single_file_visit",
    "text": "A cartless visit to a single-file aisle must end by returning to a wide clear bay before continuing.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "wideClearBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cartlessInSingleFile": {
          "and": [
            {
              "not": "hasCart"
            },
            "singleFileAisle"
          ]
        },
        "cartlessAtWideClearBay": {
          "and": [
            {
              "not": "hasCart"
            },
            "wideClearBay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessInSingleFile",
      "discharge": "cartlessAtWideClearBay"
    }
  }
]
